// spec: specs/hal-engine-tool-input-validation/spec.md#9
it('rejects a missing location from the current dynamic schema', async () => {
  const registry = new ToolRegistry();
  let definition: ToolDefinition = {
    name: 'weather',
    description: 'Weather',
    inputSchema: {type: 'object'},
  };
  const inputs: Record<string, unknown>[] = [];
  registry.register(
    () => definition,
    async input => {
      inputs.push(input);
      return 'forecast';
    }
  );
  await registry.execute('weather', {});
  definition = {
    ...definition,
    inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
  };
  const response = await registry.execute('weather', {});

  expect({rejected: /required.*location|location.*required/i.test(response.result), inputs}).toEqual({
    rejected: true,
    inputs: [{}],
  });
});
EOF
